        TEST_PROFILE['email'] = config['email']
    except (KeyError, NameError):
        pass
    try:
        TEST_PROFILE['kenlm'] = {'source_dir': config['kenlm']['source_dir']}
    except (KeyError, NameError):
        pass
    return TEST_PROFILE

